import "C"
import (
    "errors"
    "fmt"
    "sync"
)

func ReadText(path string) (string, error) {
    cPath := C.CString(path)
    defer C.free(unsafe.Pointer(cPath))

    var err C.int
    result := C.read_text_file(cPath, &err)

    if result == nil {
        switch int(err) {
        case 1:
            return "", fmt.Errorf("file not found: %s", path)
        case 2:
            return "", fmt.Errorf("permission denied: %s", path)
        default:
            return "", errors.New("unknown error")
        }
    }

    goStr := C.GoString(result)
    C.free(unsafe.Pointer(result))
    return goStr, nil
}

func main() {
    var wg sync.WaitGroup

    for _, path := range []string{"file1.txt", "file2.txt"} {
        wg.Add(1)
        go func(p string) {
            defer wg.Done()
            content, err := ReadText(p)
            if err != nil {
                fmt.Printf("Error reading %s: %v\n", p, err)
                return
            }
            fmt.Printf("Read %d bytes from %s\n", len(content), p)
        }(path)
    }

    wg.Wait()
}
